"""Process settings. Secret values stay out of logs, responses, and repr."""

from __future__ import annotations

from typing import Literal
from urllib.parse import urlsplit

from pydantic import Field, SecretStr, ValidationInfo, field_validator, model_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

from happen_api.catalog import CONTRACT_VERSION

AppEnv = Literal["development", "production"]
LogLevel = Literal["debug", "info", "warning", "error"]


def _origin(value: str, *, app_env: AppEnv) -> str:
    parsed = urlsplit(value.strip())
    if parsed.scheme not in {"http", "https"} or parsed.hostname is None:
        raise ValueError("CORS origin must be an absolute http or https origin")
    if parsed.username or parsed.password or parsed.query or parsed.fragment:
        raise ValueError("CORS origin must not include credentials, a query, or a fragment")
    if parsed.path not in {"", "/"} or "*" in value:
        raise ValueError("CORS origin must be an exact origin without a path or wildcard")
    host = parsed.hostname
    local = host in {"localhost", "127.0.0.1"}
    if app_env == "production":
        if parsed.scheme != "https" or local:
            raise ValueError("Production CORS allows only the exact https frontend origin")
    elif not local:
        raise ValueError("Development CORS allows only local origins")
    port = f":{parsed.port}" if parsed.port is not None else ""
    return f"{parsed.scheme}://{host}{port}"


class Settings(BaseSettings):
    """Runtime configuration loaded from the environment."""

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        extra="ignore",
        case_sensitive=True,
        populate_by_name=True,
    )

    app_env: AppEnv = Field(alias="APP_ENV")
    cors_allowed_origins: str = Field(alias="CORS_ALLOWED_ORIGINS")
    hf_model_repo: str = Field(alias="HF_MODEL_REPO", min_length=1)
    hf_model_revision: str = Field(alias="HF_MODEL_REVISION", min_length=1)
    model_filename: str = Field(alias="MODEL_FILENAME", min_length=1)
    model_sha256: str = Field(alias="MODEL_SHA256", pattern=r"^[0-9a-f]{64}$")
    happen_live_enabled: bool = Field(alias="HAPPEN_LIVE_ENABLED")
    log_level: LogLevel = Field(alias="LOG_LEVEL")
    serpapi_api_key: SecretStr = Field(alias="SERPAPI_API_KEY", default=SecretStr(""))
    hf_token: SecretStr = Field(alias="HF_TOKEN", default=SecretStr(""), repr=False)
    contract_version: str = CONTRACT_VERSION

    @field_validator("log_level", mode="before")
    @classmethod
    def lowercase_level(cls, value: object) -> object:
        if isinstance(value, str):
            return value.lower()
        return value

    @field_validator("model_sha256")
    @classmethod
    def lowercase_checksum(cls, value: str) -> str:
        return value.lower()

    @field_validator("cors_allowed_origins")
    @classmethod
    def parse_origins(cls, value: str, info: ValidationInfo) -> str:
        app_env = info.data.get("app_env")
        if app_env not in {"development", "production"}:
            raise ValueError("APP_ENV must be development or production")
        parts = [part.strip() for part in value.split(",") if part.strip()]
        if not parts:
            raise ValueError("At least one CORS origin is required")
        normalized = [_origin(part, app_env=app_env) for part in parts]
        if len(set(normalized)) != len(normalized):
            raise ValueError("CORS origins must be unique")
        return ",".join(normalized)

    @model_validator(mode="after")
    def live_mode_requires_key(self) -> Settings:
        if self.happen_live_enabled and not self.serpapi_api_key.get_secret_value().strip():
            raise ValueError("Live mode requires SERPAPI_API_KEY to be configured")
        return self

    @property
    def allowed_origins(self) -> tuple[str, ...]:
        return tuple(self.cors_allowed_origins.split(","))

    @property
    def live_configured(self) -> bool:
        return self.happen_live_enabled and bool(self.serpapi_api_key.get_secret_value().strip())


def get_settings() -> Settings:
    """Load settings. Invalid configuration raises and the process does not start."""

    return Settings()

"""JSON logs with secret-bearing fields removed before output."""

from __future__ import annotations

import json
import logging
import re
import sys
from datetime import UTC, datetime

_SECRET_FIELD = re.compile(r"(key|token|secret|authorization|cookie)", re.IGNORECASE)
_LOGGER_NAME = "happen"


class SecretRedactionFilter(logging.Filter):
    """Replace values whose field names look like credentials."""

    def filter(self, record: logging.LogRecord) -> bool:
        for name, value in list(record.__dict__.items()):
            if _SECRET_FIELD.search(name):
                setattr(record, name, "[redacted]")
                continue
            if isinstance(value, dict):
                setattr(record, name, _redact_mapping(value))
        return True


def _redact_mapping(value: dict[str, object]) -> dict[str, object]:
    redacted: dict[str, object] = {}
    for key, item in value.items():
        if _SECRET_FIELD.search(str(key)):
            redacted[key] = "[redacted]"
        elif isinstance(item, dict):
            redacted[key] = _redact_mapping(item)
        else:
            redacted[key] = item
    return redacted


class JsonFormatter(logging.Formatter):
    """One JSON object per log line, limited to operational fields."""

    _FIELDS = (
        "request_id",
        "endpoint",
        "status_code",
        "duration_ms",
        "error_code",
        "mode",
    )

    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, object] = {
            "time": datetime.now(UTC).isoformat(),
            "level": record.levelname.lower(),
            "message": record.getMessage(),
        }
        for name in self._FIELDS:
            if hasattr(record, name):
                payload[name] = getattr(record, name)
        return json.dumps(payload, separators=(",", ":"))


def configure_logging(level: str) -> logging.Logger:
    logger = logging.getLogger(_LOGGER_NAME)
    logger.setLevel(level.upper())
    if not any(isinstance(item, JsonFormatter) for item in _formatters(logger)):
        handler = logging.StreamHandler(sys.stdout)
        handler.setFormatter(JsonFormatter())
        handler.addFilter(SecretRedactionFilter())
        logger.addHandler(handler)
    logger.propagate = False
    return logger


def _formatters(logger: logging.Logger) -> list[logging.Formatter]:
    return [handler.formatter for handler in logger.handlers if handler.formatter is not None]


def get_logger() -> logging.Logger:
    return logging.getLogger(_LOGGER_NAME)

