/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_API_BASE_URL?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

import { z } from "zod";

export const SUPPORTED_CONTRACT_MAJOR = 1;

export const canonicalPresetSchema = z.object({
  neighborhood: z.string().min(1),
  restaurant_category: z.string().min(1),
  arrival_start: z.string().regex(/^\d{2}:\d{2}$/),
  arrival_end: z.string().regex(/^\d{2}:\d{2}$/),
  desired_experience: z.string().min(1),
  priorities: z.array(z.string().min(1)).length(3),
});

export const metaSchema = z.object({
  contract_version: z.string().min(1),
  service_version: z.string().min(1),
  supported_neighborhoods: z.array(z.string().min(1)).min(1),
  supported_categories: z.array(z.string().min(1)).min(1),
  supported_experiences: z.array(z.string().min(1)).min(1),
  priority_dimensions: z.array(z.string().min(1)).length(3),
  canonical_preset: canonicalPresetSchema,
  fixture_available: z.boolean(),
  live_available: z.boolean(),
  model_status: z.enum(["not_loaded", "loading", "ready", "unavailable"]),
  scoring_policy_version: z.string().min(1),
  timezone: z.string().min(1),
});

export type CanonicalPreset = z.infer<typeof canonicalPresetSchema>;
export type ServiceMeta = z.infer<typeof metaSchema>;

export const LOCAL_PRESET: CanonicalPreset = {
  neighborhood: "indiranagar",
  restaurant_category: "restaurants",
  arrival_start: "18:00",
  arrival_end: "21:00",
  desired_experience: "easier_conversation",
  priorities: ["conversation", "short_wait", "seating"],
};

export function contractMajor(version: string): number | null {
  const major = version.split(".")[0] ?? "";
  if (!/^\d+$/.test(major)) {
    return null;
  }
  return Number(major);
}

export function apiOrigin(configured = import.meta.env.VITE_API_BASE_URL): string {
  const value = configured?.trim() ?? "";
  if (!value) {
    return "";
  }
  const url = new URL(value);
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new Error("API base URL must use http or https");
  }
  return url.origin;
}

export function metaUrl(origin = apiOrigin()): string {
  return `${origin}/api/v1/meta`;
}

type Sleep = (milliseconds: number) => Promise<void>;

const defaultSleep: Sleep = (milliseconds) =>
  new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });

export async function loadMetadata(
  fetchImpl: typeof fetch = fetch,
  options: { origin?: string; retryDelayMs?: number; sleep?: Sleep } = {},
): Promise<ServiceMeta> {
  const url = metaUrl(options.origin ?? apiOrigin());
  const sleep = options.sleep ?? defaultSleep;
  const retryDelayMs = options.retryDelayMs ?? 1000;
  let lastError: unknown;

  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      const response = await fetchImpl(url, {
        headers: { Accept: "application/json" },
        signal: AbortSignal.timeout(3000),
      });
      if (!response.ok) {
        throw new Error(`metadata status ${response.status}`);
      }
      return metaSchema.parse(await response.json());
    } catch (error) {
      lastError = error;
      if (attempt === 0) {
        await sleep(retryDelayMs);
      }
    }
  }

  throw lastError instanceof Error ? lastError : new Error("metadata unavailable");
}

import { describe, expect, it, vi } from "vitest";
import {
  LOCAL_PRESET,
  SUPPORTED_CONTRACT_MAJOR,
  contractMajor,
  loadMetadata,
  metaSchema,
} from "./meta";

const meta = {
  contract_version: "1.0.0",
  service_version: "0.1.0",
  supported_neighborhoods: ["indiranagar"],
  supported_categories: ["restaurants"],
  supported_experiences: ["easier_conversation"],
  priority_dimensions: ["conversation", "short_wait", "seating"],
  canonical_preset: LOCAL_PRESET,
  fixture_available: false,
  live_available: false,
  model_status: "not_loaded",
  scoring_policy_version: "v1",
  timezone: "Asia/Kolkata",
};

describe("metadata contract", () => {
  it("accepts the locked metadata shape and ignores additive fields", () => {
    const parsed = metaSchema.parse({ ...meta, future_field: "ignored" });
    expect(parsed.canonical_preset).toEqual(LOCAL_PRESET);
    expect(contractMajor(parsed.contract_version)).toBe(SUPPORTED_CONTRACT_MAJOR);
  });

  it("rejects a metadata document that omits the preset", () => {
    const { canonical_preset: _preset, ...incomplete } = meta;
    expect(() => metaSchema.parse(incomplete)).toThrow();
  });

  it("retries once and then fails without returning a partial document", async () => {
    const fetchImpl = vi.fn<typeof fetch>(async () => {
      throw new Error("offline");
    });
    const sleep = vi.fn(async () => undefined);
    await expect(
      loadMetadata(fetchImpl, { origin: "http://127.0.0.1:8000", retryDelayMs: 1000, sleep }),
    ).rejects.toThrow("offline");
    expect(fetchImpl).toHaveBeenCalledTimes(2);
    expect(sleep).toHaveBeenCalledWith(1000);
  });
});

const LABELS: Record<string, string> = {
  indiranagar: "Indiranagar",
  restaurants: "Restaurants",
  easier_conversation: "Easier conversation",
  conversation: "Easier conversation",
  short_wait: "Shorter waiting",
  seating: "Better seating",
};

export function labelFor(value: string): string {
  return LABELS[value] ?? value;
}

export function moveItem(values: string[], index: number, direction: -1 | 1): string[] {
  const target = index + direction;
  if (target < 0 || target >= values.length) {
    return values;
  }
  const next = [...values];
  const [item] = next.splice(index, 1);
  if (!item) {
    return values;
  }
  next.splice(target, 0, item);
  return next;
}

import { useEffect, useId, useState } from "react";
import {
  LOCAL_PRESET,
  SUPPORTED_CONTRACT_MAJOR,
  type CanonicalPreset,
  type ServiceMeta,
  contractMajor,
  loadMetadata,
} from "../lib/api/meta";
import { labelFor, moveItem } from "../lib/labels";

type ShellState =
  | { status: "loading" }
  | { status: "unavailable" }
  | { status: "mismatch"; meta: ServiceMeta }
  | { status: "ready"; meta: ServiceMeta };

const REPOSITORY_URL = "https://github.com/kernelKain/happen";

export function App() {
  const [reloadKey, setReloadKey] = useState(0);
  const [shell, setShell] = useState<ShellState>({ status: "loading" });
  const [draft, setDraft] = useState<CanonicalPreset>(LOCAL_PRESET);
  const statusId = useId();

  useEffect(() => {
    let active = true;
    setShell({ status: "loading" });
    loadMetadata()
      .then((meta) => {
        if (!active) {
          return;
        }
        setDraft(meta.canonical_preset);
        if (contractMajor(meta.contract_version) !== SUPPORTED_CONTRACT_MAJOR) {
          setShell({ status: "mismatch", meta });
          return;
        }
        setShell({ status: "ready", meta });
      })
      .catch(() => {
        if (active) {
          setShell({ status: "unavailable" });
        }
      });
    return () => {
      active = false;
    };
  }, [reloadKey]);

  const meta = shell.status === "ready" || shell.status === "mismatch" ? shell.meta : null;
  const preset = meta?.canonical_preset ?? LOCAL_PRESET;
  const choices = {
